const out = [];
for (const it of $input.all()) {
  const v = it.json.messages ? it.json : (it.json.entry?.[0]?.changes?.[0]?.value ?? it.json);
  for (const m of (v.messages || []))
    out.push({ json: { channel: 'whatsapp', thread_id: m.from, from_value: m.from, from_type: 'phone',
      text: m.text?.body || '', received_at: new Date(Number(m.timestamp) * 1000).toISOString(), raw_id: m.id } });
}
return out;

const j = $json;
const from = String(j.from?.value?.[0]?.address || '').toLowerCase();
return { json: { channel: 'email', thread_id: j.threadId, from_value: from, from_type: 'email',
  text: String(j.text || j.snippet || '').split(/\nOn .+ wrote:/)[0].trim().slice(0, 3000),
  received_at: new Date(j.date || Date.now()).toISOString(), raw_id: j.id, subject: j.subject || '' } };

const v = $json.from_type === 'phone'
  ? '+234' + String($json.from_value).replace(/\D/g, '').replace(/^(234|0)/, '')
  : String($json.from_value).trim().toLowerCase();
const claimed = [
  ...(String($json.text).match(/[\w.+-]+@[\w-]+\.[\w.-]+/g) || []).map(e => e.toLowerCase()),
  ...(String($json.text).match(/(\+?234|0)[789][01]\d{8}/g) || []).map(p => '+234' + p.replace(/\D/g, '').replace(/^(234|0)/, ''))
].filter(c => c !== v);
const code = (String($json.text).match(/\b\d{6}\b/) || [])[0] || '';
return { json: { ...$json, from_value: v, claimed: claimed.join(','), code } };

