// Priority, owner and response target in code (5.7).
const n = $('Normalise identity').item.json;
const c = $('Upsert conversation').item.json;
const a = $json.output || $json;
const handover = a.handover || a.urgent || ['complaint', 'refund'].includes(a.intent);
const owner = handover ? 'Tolu' : 'Sage Desk';
const minutes = handover ? (a.urgent ? 15 : 60) : 5;
const meta = ['facebook', 'instagram'].includes(n.channel);
const windowOpen = (Date.now() - new Date(n.received_at)) / 36e5 <= 24;   // customer service window for WhatsApp / Meta DMs
const auto = !handover && (n.channel === 'email' || windowOpen);
return { json: { ...n, conversation_id: c.conversation_id, customer_id: c.customer_id,
  reply_channel: n.channel, reply: a.reply, intent: a.intent, handover: handover || !auto,
  owner, kind: handover ? 'complaint' : 'question', sla_due_at: new Date(Date.now() + minutes * 60000).toISOString(),
  why: !windowOpen && !handover ? 'customer window closed: no automatic reply' : '' } };

