parameters.query:
WITH m AS (
  INSERT INTO messages (conversation_id, channel, thread_id, direction, text, at) VALUES ($1, $2, $3, 'out', $4, now())
), c AS (
  UPDATE conversations SET first_reply_at = coalesce(first_reply_at, now()) WHERE conversation_id = $1
)
SELECT DISTINCT ON (channel, thread_id) channel, thread_id,
  (SELECT i.value FROM identities i JOIN conversations cv ON cv.customer_id = i.customer_id
   WHERE cv.conversation_id = $1 AND i.type = 'email' AND i.verified LIMIT 1) AS email
FROM messages WHERE conversation_id = $1 AND channel <> $2 AND direction = 'in' AND at > now() - interval '3 days';
